+package main
+
+import (
+	"fmt"
+	"os"
+
+	"github.com/preslavmihaylov/todocheck/config"
+	"github.com/preslavmihaylov/todocheck/issuetracker/factory"
+)
+
+func main() {
+	if len(os.Args) < 3 {
+		fmt.Println("Usage: go run test_exists.go <issue_tracker_type> <origin>")
+		os.Exit(1)
+	}
+
+	issueTrackerType := config.IssueTracker(os.Args[1])
+	origin := os.Args[2]
+
+	authCfg := &config.Auth{
+		Type: config.AuthTypeNone,
+	}
+
+	tracker, err := factory.NewIssueTrackerFrom(issueTrackerType, authCfg, origin)
+	if err != nil {
+		fmt.Printf("Error creating issue tracker: %v\n", err)
+		os.Exit(1)
+	}
+
+	exists := tracker.Exists()
+	fmt.Printf("Issue tracker exists: %v\n", exists)
+}
